def solve() -> int:
    hours_worked = 60
    if hours_worked <= 40:
        pay = hours_worked * 25
    else:
        pay = 40 * 25 + 10 * 30 + (hours_worked - 40) * 40
    result = pay
    return result

def solve() -> int:
    hourly_rate_1 = 15
    hourly_rate_2 = 20
    hours_worked = 45
    if hours_worked <= 35:
        total_earnings = hourly_rate_1 * hours_worked
    else:
        total_earnings = hourly_rate_1 * 35 + hourly_rate_2 * (hours_worked - 35)
    result = total_earnings
    return result

